# Check which colors appear in the grid
colors = {}
for r, row in enumerate(grid):
    for c, val in enumerate(row):
        if val not in colors:
            colors[val] = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}
        colors[val]['min_r'] = min(colors[val]['min_r'], r)
        colors[val]['max_r'] = max(colors[val]['max_r'], r)
        colors[val]['min_c'] = min(colors[val]['min_c'], c)
        colors[val]['max_c'] = max(colors[val]['max_c'], c)

print("Color bounding boxes:")
for c, bbox in colors.items():
    print(f"Color {c}: rows {bbox['min_r']}-{bbox['max_r']}, cols {bbox['min_c']}-{bbox['max_c']}")

